import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const router = express.Router();
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 5 * 1024 * 1024 } });

interface MatchResult {
  matchScore: number;
  matchedKeywords: string[];
  missingKeywords: string[];
}

function analyzeResumeText(resumeText: string, jobDescription: string): MatchResult {
  const cleanText = resumeText.toLowerCase();
  const rawKeywords = jobDescription
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')
    .split(/\s+/);

  const stopWords = new Set(['and', 'the', 'to', 'a', 'of', 'in', 'for', 'is', 'on', 'with', 'an']);
  const keywords = Array.from(new Set(rawKeywords.filter(w => w.length > 2 && !stopWords.has(w))));

  const matchedKeywords: string[] = [];
  const missingKeywords: string[] = [];

  keywords.forEach(keyword => {
    if (cleanText.includes(keyword)) {
      matchedKeywords.push(keyword);
    } else {
      missingKeywords.push(keyword);
    }
  });

  const total = keywords.length;
  const matchScore = total > 0 ? Math.round((matchedKeywords.length / total) * 100) : 0;

  return { matchScore, matchedKeywords, missingKeywords };
}

router.post('/scan', upload.single('resume'), async (req: Request, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No PDF file uploaded.' });
      return;
    }

    const jobDescription = req.body.jobDescription || '';
    if (!jobDescription) {
      res.status(400).json({ error: 'Job description is required.' });
      return;
    }

    const pdfData = await pdfParse(req.file.buffer);
    const analysis = analyzeResumeText(pdfData.text, jobDescription);

    res.status(200).json({
      success: true,
      fileName: req.file.originalname,
      ...analysis,
    });
  } catch (error: any) {
    res.status(500).json({ error: 'Failed to parse PDF resume.', details: error.message });
  }
});

export default router;

import React, { useState } from 'react';

interface ScanResult {
  fileName: string;
  matchScore: number;
  matchedKeywords: string[];
  missingKeywords: string[];
}

export const AnimatedMatchScoreCard: React.FC = () => {
  const [jobDescription, setJobDescription] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ScanResult | null>(null);

  const handleScan = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file || !jobDescription) return;

    setLoading(true);
    const formData = new FormData();
    formData.append('resume', file);
    formData.append('jobDescription', jobDescription);

    try {
      const response = await fetch('/api/scan', { method: 'POST', body: formData });
      const data = await response.json();
      if (data.success) setResult(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto p-6 bg-white rounded-xl shadow-lg border border-gray-100">
      <h2 className="text-2xl font-bold text-gray-800 mb-4">AI Resume Keyword Scanner</h2>
      <form onSubmit={handleScan} className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-700">Job Description</label>
          <textarea
            value={jobDescription}
            onChange={(e) => setJobDescription(e.target.value)}
            rows={4}
            className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 border"
            placeholder="Paste target job description here..."
            required
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700">Upload Resume (PDF)</label>
          <input
            type="file"
            accept=".pdf"
            onChange={(e) => e.target.files && setFile(e.target.files[0])}
            className="mt-1 block w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-md file:border-0 file:text-sm file:font-semibold file:bg-indigo-50 file:text-indigo-700 hover:file:bg-indigo-100"
            required
          />
        </div>
        <button
          type="submit"
          disabled={loading}
          className="w-full py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none disabled:opacity-50"
        >
          {loading ? 'Analyzing Resume...' : 'Scan Match Score'}
        </button>
      </form>

      {result && (
        <div className="mt-8 space-y-6">
          <div className="bg-gray-50 p-4 rounded-lg">
            <div className="flex justify-between items-center mb-2">
              <span className="text-sm font-medium text-gray-600">Match Score</span>
              <span className="text-2xl font-bold text-indigo-600">{result.matchScore}%</span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-3 overflow-hidden">
              <div
                className="bg-indigo-600 h-3 rounded-full transition-all duration-1000 ease-out"
                style={{ width: `${result.matchScore}%` }}
              />
            </div>
          </div>

          <div>
            <h4 className="text-sm font-semibold text-green-700 mb-2">Matched Keywords ({result.matchedKeywords.length})</h4>
            <div className="flex flex-wrap gap-2">
              {result.matchedKeywords.map((kw, i) => (
                <span key={i} className="px-2.5 py-1 bg-green-100 text-green-800 text-xs font-medium rounded-full">{kw}</span>
              ))}
            </div>
          </div>

          <div>
            <h4 className="text-sm font-semibold text-red-700 mb-2">Missing Keywords ({result.missingKeywords.length})</h4>
            <div className="flex flex-wrap gap-2">
              {result.missingKeywords.map((kw, i) => (
                <span key={i} className="px-2.5 py-1 bg-red-100 text-red-800 text-xs font-medium rounded-full">{kw}</span>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
